def getUIComponents(status=None, category_key=None, release_id=None, q=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0341000" if __import__("os").path.isdir("./environment_mix/0341000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- validation ---
    status_enum = {"active", "deprecated", "hidden"}
    cat_enum = {"layout", "media", "motion", "text_reveal", "text_effects", "buttons", "effects", "widgets", "backgrounds", "devices"}
    sort_by_enum = {"display_name", "slug", "created_at", "updated_at"}
    sort_order_enum = {"asc", "desc"}

    if status is not None and (not isinstance(status, str) or status not in status_enum):
        return _err("VALIDATION_ERROR", "Invalid `status`.", allowed=sorted(status_enum))
    if category_key is not None and (not isinstance(category_key, str) or category_key not in cat_enum):
        return _err("VALIDATION_ERROR", "Invalid `category_key`.", allowed=sorted(cat_enum))
    if release_id is not None:
        if not isinstance(release_id, str):
            return _err("VALIDATION_ERROR", "Invalid `release_id` type.")
        if not re.match(r"^mui_rel_[0-9A-Z]{18,}$", release_id):
            return _err("VALIDATION_ERROR", "Malformed `release_id`.")
    if q is not None and not isinstance(q, str):
        return _err("VALIDATION_ERROR", "Invalid `q` type.")
    if sort_by is not None and (not isinstance(sort_by, str) or sort_by not in sort_by_enum):
        return _err("VALIDATION_ERROR", "Invalid `sort_by`.", allowed=sorted(sort_by_enum))
    if sort_order is not None and (not isinstance(sort_order, str) or sort_order not in sort_order_enum):
        return _err("VALIDATION_ERROR", "Invalid `sort_order`.", allowed=sorted(sort_order_enum))
    if limit is not None:
        if not isinstance(limit, int):
            return _err("VALIDATION_ERROR", "Invalid `limit` type.")
        if limit < 1 or limit > 200:
            return _err("VALIDATION_ERROR", "`limit` must be between 1 and 200.")
    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "Invalid `cursor` type.")

    # defaults
    if sort_by is None:
        sort_by = "display_name"
    if sort_order is None:
        sort_order = "asc"
    if limit is None:
        limit = 50

    # --- load store ---
    components = _load("components.json")
    memberships = _load("component_category_memberships.json")
    categories = _load("component_categories.json")
    impls = _load("component_implementations.json")
    releases = _load("catalog_releases.json")
    request_logs = _load("request_logs.json")

    # --- cursor decode ---
    def _decode_cursor(c):
        # Supports base64url of json {"v":1,"sort":..., "order":..., "after":[...]} or raw legacy token "field:value|id"
        if not c:
            return None
        try:
            pad = "=" * ((4 - (len(c) % 4)) % 4)
            raw = base64.urlsafe_b64decode((c + pad).encode("utf-8")).decode("utf-8")
            obj = json.loads(raw)
            if isinstance(obj, dict) and obj.get("v") == 1:
                if obj.get("sort") != sort_by or obj.get("order") != sort_order:
                    return _err("VALIDATION_ERROR", "Cursor sort does not match request.", cursor_sort=obj.get("sort"), cursor_order=obj.get("order"))
                after = obj.get("after")
                if not (isinstance(after, list) and len(after) == 2 and isinstance(after[1], str)):
                    return _err("VALIDATION_ERROR", "Malformed cursor.")
                return ("ok", after)
        except Exception:
            pass
        # fallback format
        if "|" in c:
            try:
                a, bid = c.split("|", 1)
                return ("ok", [a, bid])
            except Exception:
                return _err("VALIDATION_ERROR", "Malformed cursor.")
        return _err("VALIDATION_ERROR", "Malformed cursor.")

    after = None
    dec = _decode_cursor(cursor)
    if isinstance(dec, dict) and "error" in dec:
        return dec
    if isinstance(dec, tuple):
        after = dec[1]

    # --- filters/join prep ---
    cat_by_id = {c.get("id"): c for c in categories if isinstance(c, dict)}
    active_cat_ids_by_key = {}
    for c in categories:
        if not isinstance(c, dict):
            continue
        if c.get("status") == "active" and c.get("key") in cat_enum and isinstance(c.get("id"), str):
            active_cat_ids_by_key.setdefault(c["key"], set()).add(c["id"])

    mems_by_component = {}
    for m in memberships:
        if not isinstance(m, dict):
            continue
        cid = m.get("component_id")
        catid = m.get("category_id")
        if not isinstance(cid, str) or not isinstance(catid, str):
            continue
        # only join active categories
        cat = cat_by_id.get(catid)
        if not cat or cat.get("status") != "active":
            continue
        mems_by_component.setdefault(cid, []).append(m)

    # release filter: components must have at least one impl in that release (any status)
    component_ids_with_impl_in_release = None
    if release_id is not None:
        rel_exists = any(isinstance(r, dict) and r.get("id") == release_id for r in releases)
        if not rel_exists:
            # Listing with nonexistent release simply yields empty; but description says "Raises VALIDATION_ERROR when ... release_id ... is"
            # It's "malformed" for validation; nonexistent is NOT_FOUND? Real list APIs usually accept and return empty.
            # We'll treat missing release as NOT_FOUND to avoid silent typo.
            return _err("NOT_FOUND", "Release not found.", release_id=release_id)
        s = set()
        for im in impls:
            if isinstance(im, dict) and im.get("release_id") == release_id and isinstance(im.get("component_id"), str):
                s.add(im["component_id"])
        component_ids_with_impl_in_release = s

    q_norm = (q or "").strip().lower()
    def _matches_q(comp):
        if not q_norm:
            return True
        slug = (comp.get("slug") or "")
        dn = (comp.get("display_name") or "")
        return (q_norm in str(slug).lower()) or (q_norm in str(dn).lower())

    # --- apply filters ---
    filtered = []
    for c in components:
        if not isinstance(c, dict):
            continue
        if c.get("status") == "hidden":
            # Business rule: never returned by getUIComponents
            continue
        if status is not None and c.get("status") != status:
            continue
        if not _matches_q(c):
            continue
        if category_key is not None:
            ok_cat_ids = active_cat_ids_by_key.get(category_key, set())
            cmems = mems_by_component.get(c.get("id"), [])
            if not any(isinstance(m, dict) and m.get("category_id") in ok_cat_ids for m in cmems):
                continue
        if component_ids_with_impl_in_release is not None:
            cid = c.get("id")
            if cid not in component_ids_with_impl_in_release:
                continue
        filtered.append(c)

    # --- sort + stable tiebreak ---
    reverse = (sort_order == "desc")
    def _key(c):
        v = c.get(sort_by)
        # normalize for consistent ordering
        if v is None:
            v = ""
        if sort_by in ("created_at", "updated_at"):
            # ISO Z sorts lexicographically if consistent; keep as string
            v = str(v)
        else:
            v = str(v).lower()
        return (v, str(c.get("id") or ""))
    filtered.sort(key=_key, reverse=reverse)

    # --- pagination ---
    def _compare_tuple(a, b):
        return (a > b) - (a < b)

    if after is not None:
        # after = [sort_value, id]
        a_sort, a_id = after[0], after[1]
        # Need to drop items <= after when asc, or >= after when desc, based on same sort key
        def _is_after(item):
            item_sort = item.get(sort_by)
            if item_sort is None:
                item_sort = ""
            if sort_by in ("created_at", "updated_at"):
                item_sort = str(item_sort)
            else:
                item_sort = str(item_sort).lower()
            item_id = str(item.get("id") or "")
            cur = (item_sort, item_id)
            aft = (str(a_sort).lower() if sort_by not in ("created_at", "updated_at") else str(a_sort), str(a_id))
            if not reverse:
                return cur > aft
            else:
                return cur < aft
        filtered = [c for c in filtered if _is_after(c)]

    page = filtered[:limit]
    has_more = len(filtered) > limit
    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_sort = last.get(sort_by)
        if last_sort is None:
            last_sort = ""
        if sort_by not in ("created_at", "updated_at"):
            last_sort = str(last_sort).lower()
        payload = {"v": 1, "sort": sort_by, "order": sort_order, "after": [last_sort, str(last.get("id") or "")]}
        token = base64.urlsafe_b64encode(json.dumps(payload, separators=(",", ":")).encode("utf-8")).decode("utf-8").rstrip("=")
        next_cursor = token

    # --- shape response including categories ---
    def _category_public(cat):
        return {
            "id": cat.get("id"),
            "key": cat.get("key"),
            "display_name": cat.get("display_name"),
            "description": cat.get("description"),
            "sort_order": cat.get("sort_order"),
            "status": cat.get("status"),
        }

    items = []
    for c in page:
        cid = c.get("id")
        cmems = mems_by_component.get(cid, [])
        cats_out = []
        for m in sorted([m for m in cmems if isinstance(m, dict)], key=lambda x: (x.get("sort_order") if isinstance(x.get("sort_order"), int) else 10**9, str(x.get("id") or ""))):
            cat = cat_by_id.get(m.get("category_id"))
            if not cat or cat.get("status") != "active":
                continue
            cats_out.append({
                "category": _category_public(cat),
                "is_primary": bool(m.get("is_primary")),
                "sort_order": m.get("sort_order"),
            })
        items.append({
            "id": c.get("id"),
            "slug": c.get("slug"),
            "display_name": c.get("display_name"),
            "summary": c.get("summary"),
            "doc_url": c.get("doc_url"),
            "repo_path": c.get("repo_path"),
            "status": c.get("status"),
            "created_at": c.get("created_at"),
            "updated_at": c.get("updated_at"),
            "categories": cats_out,
        })

    # --- request log (observable dynamics) ---
    latency_ms = int((time.time() - start) * 1000)
    request_logs.append({
        "id": "req_" + hashlib.sha256((now + "|getUIComponents|" + str(time.time())).encode("utf-8")).hexdigest()[:24],
        "endpoint": "getUIComponents",
        "status": "ok",
        "http_status": 200,
        "latency_ms": latency_ms,
        "timestamp": now,
    })
    _save("request_logs.json", request_logs)

    return {
        "object": "list",
        "data": items,
        "total": len(filtered) + (0 if after is None else 0),
        "limit": limit,
        "has_more": bool(has_more),
        "next_cursor": next_cursor,
        "sort_by": sort_by,
        "sort_order": sort_order,
    }

def getLayout(release_id=None, version=None, framework=None, language=None, status=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0341000" if __import__("os").path.isdir("./environment_mix/0341000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getLayout"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_logfile():
        for fname in ("request_logs.json", "api_requests.json", "api_request_logs.json", "usage_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return None

    def _log(status_code, error_code=None):
        fname = _pick_logfile()
        if not fname:
            return
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        rows.append({
            "id": "mui_req_" + secrets.token_hex(12).upper(),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": int(status_code),
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(fname, rows)

    try:
        # Validation (relaxed: allow both release_id and version but ignore them; reads always use active published release)
        if release_id is not None:
            if not isinstance(release_id, str):
                _log(400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "release_id must be a string", field="release_id")
            # pattern per tool schema
            if not re.match(r"^mui_rel_[0-9A-Z]{18,}$", release_id):
                _log(400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "release_id does not match required format", field="release_id")
        if version is not None and not isinstance(version, str):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "version must be a string", field="version")

        allowed_framework = {"react", "nextjs", "remix", "vite", "generic"}
        allowed_language = {"tsx", "ts", "jsx", "js", "mdx", "css"}
        allowed_status = {"active", "superseded", "removed"}
        if framework is not None and (not isinstance(framework, str) or framework not in allowed_framework):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid framework", field="framework", allowed=sorted(allowed_framework))
        if language is not None and (not isinstance(language, str) or language not in allowed_language):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid language", field="language", allowed=sorted(allowed_language))
        if status is not None and (not isinstance(status, str) or status not in allowed_status):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=sorted(allowed_status))

        releases = _load("catalog_releases.json")
        categories = _load("component_categories.json")
        components = _load("components.json")
        memberships = _load("component_category_memberships.json")
        impls = _load("component_implementations.json")

        # Select the single active published release (business rule)
        active_release = None
        for r in releases if isinstance(releases, list) else []:
            if isinstance(r, dict) and r.get("is_active") is True and r.get("status") == "published":
                active_release = r
                break
        if not active_release:
            _log(401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No active published catalog release available")

        # Find category by key=layout and status=active
        cat = None
        for c in categories if isinstance(categories, list) else []:
            if isinstance(c, dict) and c.get("key") == "layout" and c.get("status") == "active":
                cat = c
                break
        if not cat:
            body = {"release": active_release, "category": {"key": "layout"}, "items": [], "count": 0}
            _log(200, None)
            return body

        cat_id = cat.get("id")

        # component ids in category memberships
        member_component_ids = set()
        for m in memberships if isinstance(memberships, list) else []:
            if isinstance(m, dict) and m.get("category_id") == cat_id:
                member_component_ids.add(m.get("component_id"))

        # components map; exclude hidden
        comp_by_id = {}
        for comp in components if isinstance(components, list) else []:
            if not isinstance(comp, dict):
                continue
            if comp.get("id") in member_component_ids and comp.get("status") != "hidden":
                comp_by_id[comp.get("id")] = comp

        # choose at most one implementation per (component_id, framework, language) from active release, status active
        chosen = {}
        for imp in impls if isinstance(impls, list) else []:
            if not isinstance(imp, dict):
                continue
            if imp.get("release_id") != active_release.get("id"):
                continue
            cid = imp.get("component_id")
            if cid not in comp_by_id:
                continue
            if imp.get("status") != "active":
                continue
            if framework is not None and imp.get("framework") != framework:
                continue
            if language is not None and imp.get("language") != language:
                continue
            if status is not None and imp.get("status") != status:
                continue

            key = (cid, imp.get("framework"), imp.get("language"))
            # deterministic pick: prefer most recently updated, then created, else first
            prev = chosen.get(key)
            if prev is None:
                chosen[key] = imp
            else:
                pu = prev.get("updated_at") or prev.get("created_at") or ""
                nu = imp.get("updated_at") or imp.get("created_at") or ""
                if isinstance(nu, str) and isinstance(pu, str) and nu > pu:
                    chosen[key] = imp

        # Build response items: include component + implementation
        items = []
        for (cid, fw, lang), imp in chosen.items():
            comp = comp_by_id.get(cid)
            if not comp:
                continue
            items.append({
                "component": comp,
                "implementation": imp,
            })

        # stable ordering: by component.slug then framework/language
        def _sort_key(it):
            comp = it.get("component") or {}
            imp = it.get("implementation") or {}
            return (comp.get("slug") or "", imp.get("framework") or "", imp.get("language") or "")
        items.sort(key=_sort_key)

        body = {
            "release": active_release,
            "category": cat,
            "items": items,
            "count": len(items),
        }
        _log(200, None)
        return body
    except Exception as e:
        _log(500, "INTERNAL_ERROR")
        return _err("VALIDATION_ERROR", "Unexpected server error", detail=str(e))

def getMedia(release_id=None, version=None, framework=None, language=None, status=None, **_extra):
    import json, os, datetime, time, re, secrets

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0341000" if __import__("os").path.isdir("./environment_mix/0341000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "getMedia"

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_logfile():
        for fname in ("request_logs.json", "api_requests.json", "api_request_logs.json", "usage_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return None

    def _log(status_code, error_code=None):
        fname = _pick_logfile()
        if not fname:
            return
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        rows.append({
            "id": "mui_req_" + secrets.token_hex(12).upper(),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": int(status_code),
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save(fname, rows)

    try:
        if release_id is not None:
            if not isinstance(release_id, str):
                _log(400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "release_id must be a string", field="release_id")
            if not re.match(r"^mui_rel_[0-9A-Z]{18,}$", release_id):
                _log(400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "release_id does not match required format", field="release_id")
        if version is not None and not isinstance(version, str):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "version must be a string", field="version")

        allowed_framework = {"react", "nextjs", "remix", "vite", "generic"}
        allowed_language = {"tsx", "ts", "jsx", "js", "mdx", "css"}
        allowed_status = {"active", "superseded", "removed"}
        if framework is not None and (not isinstance(framework, str) or framework not in allowed_framework):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid framework", field="framework", allowed=sorted(allowed_framework))
        if language is not None and (not isinstance(language, str) or language not in allowed_language):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid language", field="language", allowed=sorted(allowed_language))
        if status is not None and (not isinstance(status, str) or status not in allowed_status):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status", field="status", allowed=sorted(allowed_status))

        releases = _load("catalog_releases.json")
        categories = _load("component_categories.json")
        components = _load("components.json")
        memberships = _load("component_category_memberships.json")
        impls = _load("component_implementations.json")

        active_release = None
        for r in releases if isinstance(releases, list) else []:
            if isinstance(r, dict) and r.get("is_active") is True and r.get("status") == "published":
                active_release = r
                break
        if not active_release:
            _log(401, "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "No active published catalog release available")

        cat = None
        for c in categories if isinstance(categories, list) else []:
            if isinstance(c, dict) and c.get("key") == "media" and c.get("status") == "active":
                cat = c
                break
        if not cat:
            body = {"release": active_release, "category": {"key": "media"}, "items": [], "count": 0}
            _log(200, None)
            return body

        cat_id = cat.get("id")

        member_component_ids = set()
        for m in memberships if isinstance(memberships, list) else []:
            if isinstance(m, dict) and m.get("category_id") == cat_id:
                member_component_ids.add(m.get("component_id"))

        comp_by_id = {}
        for comp in components if isinstance(components, list) else []:
            if not isinstance(comp, dict):
                continue
            if comp.get("id") in member_component_ids and comp.get("status") != "hidden":
                comp_by_id[comp.get("id")] = comp

        chosen = {}
        for imp in impls if isinstance(impls, list) else []:
            if not isinstance(imp, dict):
                continue
            if imp.get("release_id") != active_release.get("id"):
                continue
            cid = imp.get("component_id")
            if cid not in comp_by_id:
                continue
            if imp.get("status") != "active":
                continue
            if framework is not None and imp.get("framework") != framework:
                continue
            if language is not None and imp.get("language") != language:
                continue
            if status is not None and imp.get("status") != status:
                continue

            key = (cid, imp.get("framework"), imp.get("language"))
            prev = chosen.get(key)
            if prev is None:
                chosen[key] = imp
            else:
                pu = prev.get("updated_at") or prev.get("created_at") or ""
                nu = imp.get("updated_at") or imp.get("created_at") or ""
                if isinstance(nu, str) and isinstance(pu, str) and nu > pu:
                    chosen[key] = imp

        items = []
        for (cid, fw, lang), imp in chosen.items():
            comp = comp_by_id.get(cid)
            if not comp:
                continue
