def getCatalogReleases(status=None, is_active=None, version=None, sort_by=None, sort_order=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0341000" if __import__("os").path.isdir("./environment_mix/0341000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    allowed_status = {"draft", "published", "deprecated"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=sorted(allowed_status))
    if is_active is not None and not isinstance(is_active, bool):
        return _err("VALIDATION_ERROR", "is_active must be a boolean.", field="is_active")
    if version is not None and not isinstance(version, str):
        return _err("VALIDATION_ERROR", "version must be a string.", field="version")

    allowed_sort_by = {"version", "published_at", "created_at", "updated_at"}
    allowed_sort_order = {"asc", "desc"}
    if sort_by is None:
        sort_by = "published_at"
    if sort_order is None:
        sort_order = "desc"
    if not isinstance(sort_by, str) or sort_by not in allowed_sort_by:
        return _err("VALIDATION_ERROR", "Invalid sort_by.", field="sort_by", allowed=sorted(allowed_sort_by))
    if not isinstance(sort_order, str) or sort_order not in allowed_sort_order:
        return _err("VALIDATION_ERROR", "Invalid sort_order.", field="sort_order", allowed=sorted(allowed_sort_order))

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit out of range (1-200).", field="limit")

    # Decode cursor if present
    start_after = None
    if cursor is not None:
        if not isinstance(cursor, str):
            return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            payload = json.loads(raw.decode("utf-8"))
            start_after = payload  # {"v": <sort_value>, "id": <id>}
            if not isinstance(start_after, dict) or "v" not in start_after or "id" not in start_after:
                return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        except Exception:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    releases = _load("catalog_releases.json")

    # Authorization: no auth model/collections provided, so all releases are viewable.
    rows = []
    for r in releases:
        if status is not None and r.get("status") != status:
            continue
        if is_active is not None and r.get("is_active") is not is_active:
            continue
        if version is not None and r.get("version") != version:
            continue
        rows.append(r)

    total = len(rows)

    # Sorting
    reverse = (sort_order == "desc")
    def sort_key(r):
        v = r.get(sort_by)
        # Normalize None to empty for stable ordering
        if v is None:
            v = ""
        return (v, r.get("id", ""))
    rows.sort(key=sort_key, reverse=reverse)

    # Apply cursor
    if start_after is not None:
        sv = start_after.get("v")
        sid = start_after.get("id")
        filtered = []
        passed = False
        for r in rows:
            kv = r.get(sort_by)
            if kv is None:
                kv = ""
            kid = r.get("id", "")
            cur_tuple = (kv, kid)
            cmp_tuple = (sv if sv is not None else "", sid if sid is not None else "")
            if not passed:
                if reverse:
                    # descending: start after means strictly less than cursor tuple
                    if cur_tuple < cmp_tuple:
                        passed = True
                else:
                    if cur_tuple > cmp_tuple:
                        passed = True
            if passed:
                filtered.append(r)
        rows = filtered

    page = rows[:limit]
    has_more = len(rows) > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        payload = {"v": (last.get(sort_by) if last.get(sort_by) is not None else ""), "id": last.get("id", "")}
        next_cursor = base64.urlsafe_b64encode(json.dumps(payload, ensure_ascii=False).encode("utf-8")).decode("utf-8").rstrip("=")

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort_by": sort_by,
            "sort_order": sort_order,
            "latency_ms": int((time.time()-t0)*1000)
        }
    }

