            pass

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return prefix + "_" + "".join(alphabet[secrets.randbelow(len(alphabet))] for _ in range(26))

    # Validate inputs
    if not isinstance(version, str) or not version.strip():
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "version must be a non-empty string", field="version")
