        releases_rows = releases["rows"]
        container = releases
    elif isinstance(releases, list):
        releases_rows = releases
        container = None
    else:
        releases_rows = []
        container = None

    # Uniqueness constraints: unique(version), unique(source_ref) (if provided)
    for r in releases_rows:
        if isinstance(r, dict) and r.get("version") == version:
            _log(409, "CONFLICT")
            return _err("CONFLICT", "version must be unique", field="version", rule="unique(version)")
    if source_ref:
        for r in releases_rows:
            if isinstance(r, dict) and r.get("source_ref") == source_ref:
                _log(409, "CONFLICT")
                return _err("CONFLICT", "source_ref must be unique", field="source_ref", rule="unique(source_ref)")

    now = _now_iso()
    new_row = {
        "id": _gen_id("mui_rel"),
        "version": version,
        "source_repo_url": source_repo_url,
        "source_ref": source_ref,
        "is_active": False,
        "published_at": None,
        "status": "draft",
        "created_at": now,
        "updated_at": now,
    }

    releases_rows.append(new_row)
    if container is not None:
        container["rows"] = releases_rows
        _save("catalog_releases.json", container)
    else:
        _save("catalog_releases.json", releases_rows)

    _log(201, None, meta={"release_id": new_row["id"]})
