def updateCatalogRelease(id, version=None, source_repo_url=None, source_ref=None, status=None, published_at=None, is_active=None, **_extra):
    import json, os, datetime, re, time, secrets
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0341000" if __import__("os").path.isdir("./environment_mix/0341000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    endpoint = "updateCatalogRelease"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

    def _pick_logfile():
        for fname in ("request_logs.json", "api_requests.json", "api_request_logs.json", "usage_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return "request_logs.json"

    def _log(http_status, error_code=None, meta=None):
        fname = _pick_logfile()
        rows = _load(fname)
        if not isinstance(rows, list):
            rows = []
        row = {
            "id": "mui_req_" + secrets.token_hex(12).upper(),
            "endpoint": endpoint,
            "timestamp": _now_iso(),
            "status": int(http_status),
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if isinstance(meta, dict):
            row.update(meta)
        rows.append(row)
        _save(fname, rows)

    def _parse_rfc3339_to_z(s):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, "published_at must be an RFC3339 timestamp string"
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                dt = datetime.datetime.fromisoformat(ss[:-1] + "+00:00")
            else:
                dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            dt = dt.astimezone(datetime.timezone.utc).replace(microsecond=0)
            return dt.isoformat().replace("+00:00", "Z"), None
        except ValueError:
            return None, "published_at must be an RFC3339 timestamp string"

    # Validate id
    if not isinstance(id, str) or not re.match(r"^mui_rel_[0-9A-Z]{18,}$", id):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id is invalid", field="id")

    if version is not None and (not isinstance(version, str) or not version.strip()):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "version must be a non-empty string", field="version")
    if isinstance(version, str):
        version = version.strip()

    if source_repo_url is not None and (not isinstance(source_repo_url, str) or not source_repo_url.strip()):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "source_repo_url must be a non-empty string when provided", field="source_repo_url")
    if isinstance(source_repo_url, str):
        source_repo_url = source_repo_url.strip()

    if source_ref is not None and (not isinstance(source_ref, str) or not source_ref.strip()):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "source_ref must be a non-empty string when provided", field="source_ref")
    if isinstance(source_ref, str):
        source_ref = source_ref.strip()

    if status is not None:
        if not isinstance(status, str):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be a string", field="status")
        if status not in ("draft", "published", "deprecated"):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of: draft, published, deprecated", field="status")

    if published_at is not None:
        published_at_norm, perr = _parse_rfc3339_to_z(published_at)
        if perr:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", perr, field="published_at")
    else:
        published_at_norm = None

    if is_active is not None and not isinstance(is_active, bool):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_active must be a boolean", field="is_active")

    # Load releases
    rel_doc = _load("catalog_releases.json")
    if isinstance(rel_doc, dict) and isinstance(rel_doc.get("rows"), list):
        releases = rel_doc["rows"]
        rel_wrap = True
    elif isinstance(rel_doc, list):
        releases = rel_doc
        rel_wrap = False
    else:
        releases = []
        rel_wrap = False

    idx = None
    for i, r in enumerate(releases):
        if isinstance(r, dict) and r.get("id") == id:
            idx = i
            break
    if idx is None:
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "catalog release not found", id=id)

    row = releases[idx]
    old_status = row.get("status")

    # Uniqueness checks for version / source_ref when changing
    if version is not None and version != row.get("version"):
        for r in releases:
            if isinstance(r, dict) and r.get("id") != id and r.get("version") == version:
                _log(409, "CONFLICT")
                return _err("CONFLICT", "version must be unique", field="version", rule="unique(version)")
    if source_ref is not None and source_ref != row.get("source_ref"):
        for r in releases:
            if isinstance(r, dict) and r.get("id") != id and r.get("source_ref") == source_ref:
                _log(409, "CONFLICT")
                return _err("CONFLICT", "source_ref must be unique", field="source_ref", rule="unique(source_ref)")

    # Lifecycle transition enforcement (only if changing status)
    if status is not None and status != old_status:
        allowed = {
            "draft": {"published"},
            "published": {"deprecated"},
            "deprecated": set(),
        }
        if old_status not in allowed or status not in allowed[old_status]:
            _log(409, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "illegal lifecycle transition", from_status=old_status, to_status=status, rule="catalog_releases.lifecycle")
        row["status"] = status
        # If publishing and published_at not provided, set now
        if status == "published" and published_at_norm is None and not row.get("published_at"):
            row["published_at"] = _now_iso()

    # Update other fields
    if version is not None:
        row["version"] = version
    if source_repo_url is not None:
        row["source_repo_url"] = source_repo_url
    if source_ref is not None:
        row["source_ref"] = source_ref
    if published_at_norm is not None:
        row["published_at"] = published_at_norm

    # Activation rules & single-active constraint
    if is_active is not None:
        if is_active is True:
            # Must be published
            if row.get("status") != "published":
                _log(409, "CONFLICT")
                return _err("CONFLICT", "cannot set is_active=true unless status='published'", field="is_active", rule="is_active implies status='published'")
            # Must have at least one active implementation for this release
            imp_doc = _load("component_implementations.json")
            if isinstance(imp_doc, dict) and isinstance(imp_doc.get("rows"), list):
                imps = imp_doc["rows"]
            elif isinstance(imp_doc, list):
                imps = imp_doc
            else:
                imps = []
            has_active_impl = any(isinstance(imp, dict) and imp.get("release_id") == id and imp.get("status") == "active" for imp in imps)
            if not has_active_impl:
                _log(409, "CONFLICT")
                return _err("CONFLICT", "cannot set is_active=true: release has no active component implementations", field="is_active", rule="activation_requires_active_implementation")
            # Enforce at most one active: deactivate all others
            for r in releases:
                if isinstance(r, dict) and r.get("id") != id and r.get("is_active") is True:
                    r["is_active"] = False
                    r["updated_at"] = _now_iso()
            row["is_active"] = True
            if row.get("published_at") in (None, ""):
                row["published_at"] = _now_iso()
        else:
            # Allowed to deactivate regardless of status
            row["is_active"] = False

    # Enforce constraint: is_active implies published (in case status wasn't changed but is_active already true)
    if row.get("is_active") is True and row.get("status") != "published":
        _log(409, "CONFLICT")
        return _err("CONFLICT", "is_active release must have status='published'", field="is_active", rule="is_active implies status='published'")

    row["updated_at"] = _now_iso()
    releases[idx] = row
    _save("catalog_releases.json", {"rows": releases} if rel_wrap else releases)

    _log(200, None, meta={"resource_id": id})
    return {"catalog_release": row}

