        for fname in ("request_logs.json", "api_requests.json", "api_request_logs.json", "usage_logs.json", "audit_logs.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return "request_logs.json"

    def _log(http_status, error_code=None, meta=None):
        try:
            fname = _pick_logfile()
            rows = _load(fname)
            if not isinstance(rows, list):
                rows = []
            row = {
                "id": "mui_req_" + secrets.token_hex(12).upper(),
                "endpoint": endpoint,
                "timestamp": _now_iso(),
                "status": int(http_status),
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
            }
            if isinstance(meta, dict):
                row.update(meta)
            rows.append(row)
            _save(fname, rows)
        except Exception:
            pass

    # Validate id
    if not isinstance(id, str) or not re.match(r"^mui_cmp_[0-9A-Z]{18,}$", id):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id is invalid", field="id")

    if display_name is not None and (not isinstance(display_name, str) or not display_name.strip()):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "display_name must be a non-empty string", field="display_name")
    if isinstance(display_name, str):
        display_name = display_name.strip()

    if summary is not None and not isinstance(summary, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "summary must be a string", field="summary")
    if doc_url is not None and not isinstance(doc_url, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "doc_url must be a string", field="doc_url")
    if repo_path is not None and not isinstance(repo_path, str):
        _log(400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "repo_path must be a string", field="repo_path")

    allowed_status = {"active", "deprecated", "hidden"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status must be one of active, deprecated, hidden", field="status", allowed=list(sorted(allowed_status)))

    if slug is not None:
        if not isinstance(slug, str) or not slug.strip():
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "slug must be a non-empty string when provided", field="slug")
        slug = slug.strip()
        if not re.match(r"^[a-z0-9]+(?:-[a-z0-9]+)*$", slug):
            _log(400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "slug must match ^[a-z0-9]+(?:-[a-z0-9]+)*$", field="slug", rule="slug pattern")

    # Load components
    components = _load("components.json")
    if isinstance(components, dict) and "rows" in components and isinstance(components["rows"], list):
        comp_rows = components["rows"]
        container = components
    elif isinstance(components, list):
        comp_rows = components
        container = None
    else:
        comp_rows = []
        container = None

    idx = None
    for i, c in enumerate(comp_rows):
        if isinstance(c, dict) and c.get("id") == id:
            idx = i
            break
    if idx is None:
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "component not found", field="id", id=id)

    comp = comp_rows[idx]
    if not isinstance(comp, dict):
        _log(404, "NOT_FOUND")
        return _err("NOT_FOUND", "component not found", field="id", id=id)

    changed = False
    now = _now_iso()

    # Slug change rules:
    # - unique(slug)
    # - immutable once referenced by any component_implementations row
    if slug is not None and slug != comp.get("slug"):
        impls = _load("component_implementations.json")
        if isinstance(impls, dict) and "rows" in impls and isinstance(impls["rows"], list):
            impl_rows = impls["rows"]
        elif isinstance(impls, list):
            impl_rows = impls
        else:
            impl_rows = []
        referenced = any(isinstance(r, dict) and r.get("component_id") == id for r in impl_rows)
        if referenced:
            _log(409, "CONFLICT")
            return _err("CONFLICT", "cannot change slug after it has been referenced by an implementation", field="slug", rule="slug immutable once referenced")
        for c in comp_rows:
            if isinstance(c, dict) and c.get("slug") == slug and c.get("id") != id:
                _log(409, "CONFLICT")
                return _err("CONFLICT", "slug must be globally unique", field="slug", rule="unique(slug)")
        comp["slug"] = slug
        changed = True

    # Lifecycle transitions
    if status is not None and status != comp.get("status"):
        transitions = {
            "active": {"deprecated", "hidden"},
            "deprecated": {"hidden"},
            "hidden": {"active"},
        }
        cur = comp.get("status")
        if cur not in transitions or status not in transitions[cur]:
            _log(409, "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "invalid status transition", field="status", from_status=cur, to_status=status)
        comp["status"] = status
        changed = True

    # Simple fields
    if display_name is not None and display_name != comp.get("display_name"):
        comp["display_name"] = display_name
        changed = True
    if summary is not None and summary != comp.get("summary"):
        comp["summary"] = summary
        changed = True
    if doc_url is not None and doc_url != comp.get("doc_url"):
        comp["doc_url"] = doc_url
        changed = True
    if repo_path is not None and repo_path != comp.get("repo_path"):
        comp["repo_path"] = repo_path
        changed = True

    if not changed:
        # idempotent: return current component (but still "success" because target exists)
        _log(200, None, meta={"component_id": id, "changed": False})
        return {"component": comp}

    comp["updated_at"] = now
    comp_rows[idx] = comp

    if container is not None:
        container["rows"] = comp_rows
        _save("components.json", container)
    else:
        _save("components.json", comp_rows)

    _log(200, None, meta={"component_id": id, "changed": True})
    return {"component": comp}
